/// The table for an OEM code page label, if it is one of ours.
pub fn table_for(label: &str) -> Option<(&'static Table, &'static str, u8)> {
    let l = label.trim().to_ascii_lowercase();
    let l = l
        .strip_prefix("cp")
        .or_else(|| l.strip_prefix("ibm"))
        .unwrap_or(&l);
    match l {
        "437" => Some((&CP437, "cp437", 0x01)),
        "850" => Some((&CP850, "cp850", 0x02)),
        "852" => Some((&CP852, "cp852", 0x64)),
        _ => None,
    }
}

/// Decodes bytes with an OEM table.
pub fn decode(table: &Table, bytes: &[u8]) -> String {
    bytes
        .iter()
        .map(|b| {
            if *b < 0x80 {
                *b as char
            } else {
                table[usize::from(*b - 0x80)]
            }
        })
        .collect()
}

/// Encodes text with an OEM table (`?` for characters outside it).
pub fn encode(table: &Table, text: &str) -> Vec<u8> {
    text.chars()
        .map(|c| {
            if (c as u32) < 0x80 {
                c as u8
            } else {
                table
                    .iter()
                    .position(|t| *t == c)
                    .map_or(b'?', |i| 0x80 + i as u8)
            }
        })
        .collect()
}
